CREATE OR REPLACE FUNCTION app.frame_css_uses_url_pattern(p_css text, p_url_pattern text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE token text[];
BEGIN
  FOR token IN SELECT regexp_matches(COALESCE(p_css,''),
    $re$/\*(?:[^*]|\*+[^*/])*\*+/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\murl[[:space:]]*\([[:space:]]*(?:"([^"]*)"|'([^']*)'|([^[:space:]"')]*))[[:space:]]*\)$re$, 'gi')
  LOOP
    IF app.frame_url_matches(COALESCE(token[1], token[2], token[3]), p_url_pattern) THEN RETURN true; END IF;
  END LOOP;
  RETURN false;
END
$function$
